svg.script:

(function() {
  var root = document.querySelector('.fm1p4-root');
  if (!root) return;

  function setActiveStage(stageId) {
    root.setAttribute('data-active-stage', stageId);
  }

  // Add click listeners to chambers and buttons
  var elements = root.querySelectorAll('[data-stage]');
  for (var i = 0; i < elements.length; i++) {
    (function(el) {
      var targetStage = el.getAttribute('data-stage');

      el.addEventListener('click', function(e) {
        e.stopPropagation();
        setActiveStage(targetStage);
      });

      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          setActiveStage(targetStage);
        }
      });
    })(elements[i]);
  }
})();
